def sync_profile_from_supabase(username):
    headers = {
        "apikey": SUPABASE_KEY,
        "Authorization": f"Bearer {SUPABASE_KEY}",
        "Accept": "application/json"
    }
    try:
        req_url = f"{SUPABASE_URL}/rest/v1/profiles?username=eq.{urllib.parse.quote(username)}&select=*"
        req = urllib.request.Request(req_url, headers=headers)
        with urllib.request.urlopen(req, timeout=4.0) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            if isinstance(data, list) and len(data) > 0:
                profile = data[0]
                cache_file = ROOT_DIR / "horus_profile.json"
                try:
                    with open(cache_file, "w", encoding="utf-8") as f:
                        json.dump(profile, f, ensure_ascii=False, indent=2)
                except Exception:
                    pass
                return profile
    except Exception:
        pass

    cache_file = ROOT_DIR / "horus_profile.json"
    if cache_file.exists():
        try:
            with open(cache_file, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass

    return {
        "username": username,
        "role": "ADMIN",
        "subscription_till": "01.01.2048",
        "balance": 1000
    }

def find_launcher_hwnd():
    user32 = ctypes.windll.user32
    user32.FindWindowExW.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_wchar_p, ctypes.c_wchar_p]
    user32.FindWindowExW.restype = ctypes.c_void_p

    hwnd = 0
    while True:
        hwnd = user32.FindWindowExW(0, hwnd, None, None)
        if not hwnd:
            break
        if not user32.IsWindowVisible(hwnd):
            continue
        cls_buff = ctypes.create_unicode_buffer(256)
        user32.GetClassNameW(hwnd, cls_buff, 256)
        cls = cls_buff.value.lower()
        if "chrome_widgetwin_1" in cls or "horus" in cls:
            length = user32.GetWindowTextLengthW(hwnd)
            if length > 0:
                buff = ctypes.create_unicode_buffer(length + 1)
                user32.GetWindowTextW(hwnd, buff, length + 1)
                title = buff.value.lower()
                if "horus" in title or "launcher" in title or "127.0.0.1" in title or "minecraft" in title or str(ACTIVE_PORT) in title:
                    return hwnd
    return None

def resize_launcher_window(width=1020, height=620):
    try:
        hwnd = find_launcher_hwnd()
        if hwnd:
            user32 = ctypes.windll.user32
            sw = user32.GetSystemMetrics(0)
            sh = user32.GetSystemMetrics(1)
            x = max(0, (sw - width) // 2)
            y = max(0, (sh - height) // 2)

            # Resizable desktop client launcher window

            SWP_SHOWWINDOW = 0x0040
            SWP_NOZORDER = 0x0004
            SWP_FRAMECHANGED = 0x0020

            user32.SetWindowPos(hwnd, 0, x, y, width, height, SWP_SHOWWINDOW | SWP_NOZORDER | SWP_FRAMECHANGED)
            return True
    except Exception:
        pass
    return False

class ResilientServer(ThreadingMixIn, HTTPServer):
    daemon_threads = True
    allow_reuse_address = False

class LauncherRequestHandler(SimpleHTTPRequestHandler):
    def send_cors_headers(self):
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_cors_headers()
        self.end_headers()

    def do_POST(self):
        global last_activity, has_connected
        last_activity = time.time()
        has_connected = True
        path = self.path.split("?")[0]

        if path.startswith("/api/action/"):
            action = path[len("/api/action/"):]
            game_resp = query_game_bridge(path, method="POST")
            if game_resp:
                resp = game_resp
            else:
                if action == "open-logs":
                    folder = ROOT_DIR / "logs"
                    if not folder.exists():
                        folder = Path(os.environ.get("APPDATA", "")) / ".minecraft" / "logs"
                    try:
                        os.startfile(folder)
                        resp = {"success": True, "message": "Папка логов открыта"}
                    except Exception as e:
                        resp = {"success": False, "error": str(e)}
                else:
                    resp = {"success": False, "error": "Игра не запущена"}
            data = json.dumps(resp, ensure_ascii=False).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_cors_headers()
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return

        if path == "/api/accounts/add":
            length = int(self.headers.get('Content-Length', 0))
            payload = json.loads(self.rfile.read(length).decode('utf-8')) if length > 0 else {}
            new_user = payload.get("username", "").strip()
            acc_data = load_accounts_data()
            if new_user:
                names = [a["username"].lower() for a in acc_data["accounts"]]
                if new_user.lower() not in names:
                    acc_data["accounts"].append({
                        "username": new_user,
                        "role": "ADMIN",
                        "avatar": f"https://mc-heads.net/avatar/{new_user}/64"
                    })
                acc_data["active"] = new_user
                save_accounts_data(acc_data)
            data = json.dumps(acc_data, ensure_ascii=False).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_cors_headers()
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
